WITH left_oracle AS (WITH w AS (SELECT mktcode,tgtcode,bizdate,lastPx/10000.0 AS px,MIN(lastPx/10000.0) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN 9 PRECEDING AND CURRENT ROW) AS lo,MAX(lastPx/10000.0) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN 9 PRECEDING AND CURRENT ROW) AS hi FROM `newzl`.`hsj_stock_hq_basic`) SELECT mktcode,tgtcode,bizdate FROM w WHERE bizdate='2026-04-14' AND CASE WHEN px IS NULL OR lo IS NULL OR hi IS NULL THEN NULL WHEN px<=lo THEN '最低' WHEN px>=hi THEN '最高' WHEN (px-lo)/NULLIF(hi-lo,0)<=0.25 THEN '低' WHEN (px-lo)/NULLIF(hi-lo,0)>=0.75 THEN '高' ELSE '中' END='最高'), right_oracle AS (WITH benchmark AS (SELECT b.volume FROM `newzl`.`hsj_stock_hq_basic` AS b INNER JOIN `newzl`.`hsj_stock_code_info` AS s ON s.mktcode=b.mktcode AND s.tgtcode=b.tgtcode WHERE s.name='贵州茅台' AND b.bizdate='2026-04-14') SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` AS b CROSS JOIN benchmark AS q WHERE b.mktcode=1 AND b.bizdate='2026-04-14' AND b.volume>q.volume), left_filtered AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM left_oracle o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE 1=1 AND q.volume>=0), right_filtered AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM right_oracle o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode=1 AND q.volume>=1) SELECT mktcode,tgtcode,bizdate FROM left_filtered UNION DISTINCT SELECT mktcode,tgtcode,bizdate FROM right_filtered;
